mapper.select:
SELECT a.id AS assetId, a.asset_code AS assetCode, a.asset_name AS assetName, a.workshop AS workshop, COUNT(o.id) AS orderCount, COALESCE(SUM(CASE WHEN o.status = 50 THEN 1 ELSE 0 END), 0) AS closedCount, COALESCE(SUM(o.downtime_minutes), 0) AS downtimeMinutes, COALESCE(ROUND(AVG(CASE WHEN o.finish_time IS NOT NULL THEN o.downtime_minutes END)), 0) AS mttrMinutes, COALESCE(ROUND(AVG(CASE WHEN o.accept_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, o.report_time, o.accept_time) END)), 0) AS responseMinutes, MAX(o.report_time) AS lastReportTime FROM eq_asset a JOIN wo_order o ON o.asset_id = a.id AND o.deleted = 0 AND o.report_time >= #{from} AND o.report_time < DATE_ADD(#{to}, INTERVAL 1 DAY) WHERE a.deleted = 0
AND a.workshop = #{workshop}
GROUP BY a.id, a.asset_code, a.asset_name, a.workshop ORDER BY downtimeMinutes DESC, orderCount DESC
